package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }

    /**
     * Test Case 1: 
     * Scenario: findConvertingContentDeserializer returns null, 
     * ctxt.findContextualValueDeserializer returns the default String deserializer.
     * Result: isDefaultDeserializer returns true, deser becomes null, returns 'this'.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenDefault() throws JsonMappingException {
        // We need to mock the behavior of findConvertingContentDeserializer. 
        // Since it's a protected method in the same class, we use a spy.
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        // Mock findConvertingContentDeserializer to return null
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // Mock findContextualValueDeserializer to return a default String deserializer
        JsonDeserializer<?> defaultStringDeser = new StringDeserializer();
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(defaultStringDeser);

        // To make isDefaultDeserializer return true for the mock, 
        // we rely on the fact that StringDeserializer is indeed the default.

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertSame(spyDeserializer, result);
    }

    /**
     * Test Case 2:
     * Scenario: findConvertingContentDeserializer returns a non-null deserializer.
     * Result: deser is not null, handleSecondaryContextualization is called.
     * If the returned deser is different from _elementDeserializer, return new StringArrayDeserializer(deser).
     */
    @Test
    public void testCreateContextual_ReturnsNewDeserializerWhenContextualized() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        JsonDeserializer<?> customDeser = mock(JsonDeserializer.class);

        // Mock findConvertingContentDeserializer to return customDeser
        doReturn(customDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // Mock handleSecondaryContextualization to return customDeser
        when(ctxt.handleSecondaryContextualization(eq(customDeser), eq(property))).thenReturn(customDeser);

        // Ensure isDefaultDeserializer returns false for customDeser
        // Since customDeser is a mock and not a StringDeserializer, isDefaultDeserializer should return false

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotNull(result);
        assertNotSame(spyDeserializer, result);
        assertTrue(result instanceof StringArrayDeserializer);
    }

    /**
     * Test Case 3:
     * Scenario: findConvertingContentDeserializer returns null,
     * ctxt.findContextualValueDeserializer returns a non-default deserializer.
     * Result: returns new StringArrayDeserializer(deser).
     */
    @Test
    public void testCreateContextual_ReturnsNewWhenFindContextualReturnsNew() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        JsonDeserializer<?> customDeser = mock(JsonDeserializer.class);

        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(customDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotNull(result);
        assertNotSame(spyDeserializer, result);
    }

    /**
     * Test Case 4:
     * Scenario: findConvertingContentDeserializer returns null,
     * ctxt.findContextualValueDeserializer returns null.
     * Result: deser is null, returns 'this'.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenAllNull() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertSame(spyDeserializer, result);
    }

    /**
     * Test Case 5:
     * Scenario: findConvertingContentDeserializer returns a deserializer that is the same as _elementDeserializer.
     * Result: returns 'this'.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenNoChange() throws JsonMappingException {
        // To test this, we need to set _elementDeserializer. 
        // Since it's private, we use a trick or rely on the default which is null.
        // If _elementDeserializer is null, and findConvertingContentDeserializer returns null, 
        // it enters the first branch.

        // Let's try the branch where deser != null but deser == _elementDeserializer.
        // This happens if findConvertingContentDeserializer returns the existing _elementDeserializer.

        // We'll use a subclass to expose the field for testing or use reflection if needed, 
        // but here we can just mock the logic.

        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        // In default state, _elementDeserializer is null.
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);
        assertSame(spyDeserializer, result);
    }
}
